"""Pure helpers behind ``vnstratlab init`` (P1-T35): minimal user overrides, render, atomic write.

The wizard only writes ``<home>/config.yaml``. It never handles secrets and never uses the network.
"""

from __future__ import annotations

import copy
import datetime as dt
import os
import tempfile
from collections.abc import Mapping
from importlib.resources import files
from pathlib import Path
from typing import Any

import yaml

from vnstratlab.config.loader import ConfigError, load_config

BOOKS = ("short", "medium", "long")
SOURCES = ("yahoo", "synthetic")
HEADER = (
    "# Generated by `vnstratlab init` on {date}.\n"
    "# Only values that differ from the packaged defaults are listed here.\n"
    "# See docs/configuration.md for every key. Secrets belong in .env, never in this file.\n"
)


def packaged_defaults() -> dict[str, Any]:
    """The packaged ``defaults.yaml`` as a plain dict."""
    text = files("vnstratlab.config").joinpath("defaults.yaml").read_text(encoding="utf-8")
    data = yaml.safe_load(text)
    return data if isinstance(data, dict) else {}


def check_capital(value: int) -> str | None:
    return None if value > 0 else "must be greater than 0"


def check_fee(value: float) -> str | None:
    return None if 0 <= value < 1 else "must be a fraction from 0 up to (not including) 1"


def check_source(value: str) -> str | None:
    return None if value in SOURCES else f"must be one of: {', '.join(SOURCES)}"


def get_path(tree: Mapping[str, Any], path: tuple[str, ...]) -> Any:
    node: Any = tree
    for key in path:
        if not isinstance(node, Mapping) or key not in node:
            return None
        node = node[key]
    return node


def _set_or_drop(tree: dict[str, Any], path: tuple[str, ...], value: Any, default: Any) -> None:
    """Set ``path`` to ``value``, or remove it (and emptied parents) when it equals the default."""
    if value != default:
        node = tree
        for key in path[:-1]:
            child = node.get(key)
            if not isinstance(child, dict):
                child = {}
                node[key] = child
            node = child
        node[path[-1]] = value
        return
    parents: list[dict[str, Any]] = [tree]
    for key in path[:-1]:
        child = parents[-1].get(key)
        if not isinstance(child, dict):
            return
        parents.append(child)
    parents[-1].pop(path[-1], None)
    for depth in range(len(path) - 1, 0, -1):
        if parents[depth]:
            break
        parents[depth - 1].pop(path[depth - 1], None)


def build_overrides(
    existing: Mapping[str, Any] | None,
    *,
    capital: Mapping[str, int | None] | None = None,
    source: str | None = None,
    brokerage_fee: float | None = None,
    defaults: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Return the user mapping to write: ``existing`` with the asked keys updated.

    A value equal to the packaged default is removed (minimal overrides); a value of ``None``
    means "not asked" and leaves the existing key alone. Other existing keys are kept.
    """
    base = defaults if defaults is not None else packaged_defaults()
    result = copy.deepcopy(dict(existing or {}))
    for book, value in (capital or {}).items():
        if value is not None:
            path = ("books", book, "capital_vnd")
            _set_or_drop(result, path, value, get_path(base, path))
    if source is not None:
        _set_or_drop(result, ("data", "source"), source, get_path(base, ("data", "source")))
    if brokerage_fee is not None:
        fee_path = ("costs", "brokerage_fee_pct")
        _set_or_drop(result, fee_path, brokerage_fee, get_path(base, fee_path))
    return result


def render_config(overrides: Mapping[str, Any], today: dt.date) -> str:
    """YAML text with the header comment; ``{}`` when there is nothing to override."""
    header = HEADER.format(date=today.isoformat())
    if not overrides:
        return header + "{}\n"
    body = yaml.safe_dump(dict(overrides), sort_keys=False, default_flow_style=False)
    return header + body


def validate_overrides(overrides: Mapping[str, Any]) -> list[str]:
    """Run the real loader on the candidate (in a scratch home); return ``path: reason`` lines."""
    with tempfile.TemporaryDirectory(prefix="vnstratlab-init-") as scratch:
        home = Path(scratch)
        (home / "config.yaml").write_text(
            yaml.safe_dump(dict(overrides)) if overrides else "{}\n", encoding="utf-8"
        )
        try:
            load_config(home)
        except ConfigError as exc:
            return list(exc.problems)
    return []


def ensure_home_dirs(paths: Any) -> None:
    """Create the home folders if missing; existing contents are never touched."""
    for folder in (paths.home, paths.data_dir, paths.strategies_dir, paths.logs_dir):
        folder.mkdir(parents=True, exist_ok=True)
    paths.backups_dir.mkdir(parents=True, exist_ok=True)


def write_config(path: Path, text: str, *, backup_stamp: str | None = None) -> Path | None:
    """Atomically write ``text`` (UTF-8, LF). Returns the backup path if one was made.

    An existing file is first copied to ``<name>.bak-<backup_stamp>`` (only when a stamp is given).
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    backup: Path | None = None
    if backup_stamp is not None and path.exists():
        backup = path.with_name(f"{path.name}.bak-{backup_stamp}")
        backup.write_bytes(path.read_bytes())
    fd, tmp_name = tempfile.mkstemp(dir=path.parent, prefix=f".{path.name}.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
        os.replace(tmp_name, path)
    except BaseException:
        Path(tmp_name).unlink(missing_ok=True)
        raise
    return backup


def packaged_config() -> Any:
    """The validated packaged defaults as an ``AppConfig`` (no user file involved)."""
    with tempfile.TemporaryDirectory(prefix="vnstratlab-init-") as scratch:
        return load_config(Path(scratch))
